<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import type { CorpusRecord } from "../api/pdfCorpus";
import { useI18nStore } from "../stores/i18n";
import CorpusFieldOwnershipBadge from "./CorpusFieldOwnershipBadge.vue";

const props=defineProps<{record:CorpusRecord;regionTypes:string[];discourseRoles:string[];busy?:boolean;savingField?:string;savedField?:string}>();
const emit=defineEmits<{resolve:[field:string,value:unknown];source:[field:string]}>();
const requiredFields=new Set(["region_type","primary_text","discourse_role"]);
const booleanFields=new Set(["primary_text","document_is_translation","is_direct_quote"]);
const numberFields=new Set(["year","publication_year"]);
const arrayFields=new Set(["document_language","original_language","semantic_function","quoted_speaker","quoted_author","quoted_work","quoted_position_holder","quoted_addressee","quoted_referent","quotation_chain","topics","concepts","persons","works_referenced"]);
const inheritedFieldSet=new Set(["work","document_title","short_title","original_title","document_author","translator","edition","publication_year","publisher","publication_place","isbn","document_language","original_language","document_is_translation"]);
const PROPOSAL_PREFILL_CONFIDENCE=.65;
const i18n=useI18nStore();
const draft=reactive<Record<string,unknown>>({});
const editing=ref("");
const fieldOrder=["region_type","primary_text","discourse_role","region_author","speaker","position_holder","target","stance","proposition_status","claim_scope","semantic_function","is_direct_quote","quoted_speaker","quoted_author","quoted_work","quoted_position_holder","quoted_addressee","quoted_referent","quotation_chain","topics","concepts","persons","works_referenced","work","document_title","short_title","original_title","document_author","translator","edition","publication_year","publisher","publication_place","isbn","document_language","original_language","document_is_translation"];
const unresolved=computed(()=>new Set([...(props.record.metadata_incomplete_fields||[]),...(props.record.metadata_review_fields||[])]));
const fields=computed(()=>fieldOrder.filter(field=>props.record.metadata_field_status?.[field]||props.record[field]!==undefined||unresolved.value.has(field)));
const activeFields=computed(()=>fields.value.filter(field=>!inheritedFieldSet.has(field)));
const inheritedFields=computed(()=>fields.value.filter(field=>inheritedFieldSet.has(field)));
const enrichmentState=computed(()=>String(props.record.metadata_enrichment_state||''));
const enrichmentPending=computed(()=>['queued','running'].includes(enrichmentState.value));
function status(field:string){return props.record.metadata_field_status?.[field]||{}}
function confidence(field:string){const value=status(field).confidence;return typeof value==='number'&&Number.isFinite(value)?value:null}
function isLlmProposal(field:string){return String(status(field).method||'').includes('llm')&&props.record[field]!==undefined&&props.record[field]!==null&&props.record[field]!==''}
function shouldPrefill(field:string){const conf=confidence(field);return !isLlmProposal(field)||conf!==null&&conf>=PROPOSAL_PREFILL_CONFIDENCE}
function initialValue(field:string){const value=shouldPrefill(field)?props.record[field]:"";return Array.isArray(value)?value.join(", "):value??""}
watch(()=>[props.record.record_id,props.record.record_revision,...fields.value],()=>{for(const field of fields.value){if(editing.value===field)continue;draft[field]=initialValue(field)}},{immediate:true});
function options(field:string){if(field==="region_type")return props.regionTypes;if(field==="discourse_role")return props.discourseRoles;return []}
function normalized(field:string){const raw=draft[field];if(arrayFields.has(field))return String(raw||"").split(",").map(v=>v.trim()).filter(Boolean);if(numberFields.has(field)&&raw!=="")return Number(raw);return raw}
function save(field:string){emit("resolve",field,normalized(field));editing.value=field}
function confirmAbsent(field:string){emit("resolve",field,null);editing.value=field}
function displayValue(field:string){const value=props.record[field];if(value===true)return i18n.t("ui.yes","Yes");if(value===false)return i18n.t("ui.no","No");if(Array.isArray(value))return value.join(", ")||"—";return value===null||value===undefined||value===""?"—":String(value)}
function isEditing(field:string){return unresolved.value.has(field)||editing.value===field}
function startEdit(field:string){editing.value=editing.value===field?"":field;if(editing.value===field&&draft[field]===undefined)draft[field]=initialValue(field)}
function confidenceLabel(field:string){const conf=confidence(field);if(conf===null)return i18n.t('pdf_corpus.confidence_not_reported','Confidence not reported');return i18n.tf('pdf_corpus.confidence_percent','Confidence: {percent}%',{percent:Math.round(conf*100)})}
</script>

<template>
<section class="metadata-review" aria-labelledby="metadata-review-title">
  <header class="metadata-head"><div><h3 id="metadata-review-title">{{i18n.t('pdf_corpus.metadata_tab','Metadata')}}</h3><p>{{i18n.t('pdf_corpus.metadata_inline_help_v48','Review and edit the eventual JSONL metadata directly. Human-saved values remain authoritative while background enrichment continues.')}}</p></div><span class="review-status" :data-state="enrichmentPending?'processing':unresolved.size?'attention':'ready'">{{enrichmentPending?i18n.t('pdf_corpus.metadata_enrichment_pending','LLM enrichment pending'):unresolved.size?i18n.tf('pdf_corpus.metadata_decisions_count','{count} decision(s)',{count:unresolved.size}):i18n.t('pdf_corpus.metadata_ready','Ready')}}</span></header><p v-if="enrichmentPending" class="enrichment-note" role="status">{{i18n.t('pdf_corpus.metadata_enrichment_pending_help','This record is editable now, but its background LLM metadata has not settled yet. Confidence and suggestions will appear as each metadata family completes.')}}</p>

  <div v-if="activeFields.length" class="metadata-table" role="list">
    <article v-for="field in activeFields" :key="field" class="metadata-row" :class="{unresolved:unresolved.has(field)}" role="listitem">
      <div class="metadata-summary"><div class="field-label"><b>{{i18n.t(`record.${field}`,field.replace(/_/g,' '))}}</b><CorpusFieldOwnershipBadge :status="String(status(field).status||'')" :method="String(status(field).method||'')" /></div><div class="field-value"><span>{{displayValue(field)}}</span></div><div class="field-actions"><button type="button" class="evidence-link" @click="emit('source',field)">{{i18n.t('pdf_corpus.view_evidence','Evidence')}}</button><button type="button" class="btn small" :disabled="busy" @click="startEdit(field)">{{editing===field?i18n.t('ui.done','Done'):i18n.t('ui.edit','Edit')}}</button></div></div>
      <div v-if="isEditing(field)" class="decision-editor"><p v-if="status(field).reason" class="decision-reason">{{status(field).reason}}</p><div class="decision-controls"><select v-if="field==='region_type'||field==='discourse_role'" v-model="draft[field]" class="control" :aria-label="i18n.t(`record.${field}`,field)"><option value="" disabled>{{i18n.t('pdf_corpus.choose_value','Choose a value…')}}</option><option v-for="value in options(field)" :key="value" :value="value">{{i18n.t(`record.enum.${field}.${value}`,value.replace(/_/g,' '))}}</option></select><fieldset v-else-if="booleanFields.has(field)" class="boolean-choice"><legend class="sr-only">{{i18n.t(`record.${field}`,field)}}</legend><label><input v-model="draft[field]" type="radio" :name="`${field}-${record.record_id}`" :value="true"> <span>{{i18n.t('ui.yes','Yes')}}</span></label><label><input v-model="draft[field]" type="radio" :name="`${field}-${record.record_id}`" :value="false"> <span>{{i18n.t('ui.no','No')}}</span></label></fieldset><input v-else v-model="draft[field]" class="control" :type="numberFields.has(field)?'number':'text'" :aria-label="i18n.t(`record.${field}`,field)"><button type="button" class="btn primary" :disabled="busy||draft[field]===''||draft[field]===undefined||(requiredFields.has(field)&&draft[field]===null)" @click="save(field)">{{savingField===field?i18n.t('pdf_corpus.saving_decision','Saving…'):i18n.t('pdf_corpus.save_field_value','Save value')}}</button><button v-if="!requiredFields.has(field)" type="button" class="btn" :disabled="busy" @click="confirmAbsent(field)">{{i18n.t('pdf_corpus.confirm_no_value','No supported value')}}</button></div><div class="decision-meta"><span v-if="isLlmProposal(field)" class="proposal" :data-strong="confidence(field)!==null&&Number(confidence(field))>=PROPOSAL_PREFILL_CONFIDENCE?'true':'false'">{{confidence(field)!==null&&Number(confidence(field))>=PROPOSAL_PREFILL_CONFIDENCE?i18n.t('pdf_corpus.llm_suggestion_selected_short','LLM suggestion selected by default'):i18n.t('pdf_corpus.llm_suggestion_low_confidence','LLM suggestion — review before selecting')}}</span><span>{{confidenceLabel(field)}}</span><span v-if="savedField===field" class="saved" role="status">{{i18n.t('pdf_corpus.decision_saved_editable','Saved — you can keep editing this value')}}</span></div></div>
    </article>
  </div>

  <details v-if="inheritedFields.length" class="inherited-metadata"><summary>{{i18n.t('pdf_corpus.inherited_metadata_section','Inherited document metadata')}} <span>{{inheritedFields.length}}</span></summary><p>{{i18n.t('pdf_corpus.inherited_metadata_help','These values come from the document manifest. Override only when this record legitimately differs from the document default.')}}</p><div class="metadata-table" role="list"><article v-for="field in inheritedFields" :key="field" class="metadata-row" role="listitem"><div class="metadata-summary"><div class="field-label"><b>{{i18n.t(`record.${field}`,field.replace(/_/g,' '))}}</b><CorpusFieldOwnershipBadge :status="String(status(field).status||'inherited')" :method="String(status(field).method||'manifest')" /></div><div class="field-value">{{displayValue(field)}}</div><div class="field-actions"><button type="button" class="btn small" :disabled="busy" @click="startEdit(field)">{{editing===field?i18n.t('ui.done','Done'):i18n.t('pdf_corpus.override_value','Override')}}</button></div></div><div v-if="editing===field" class="decision-editor"><div class="decision-controls"><input v-model="draft[field]" class="control" :type="numberFields.has(field)?'number':'text'" :aria-label="i18n.t(`record.${field}`,field)"><button type="button" class="btn primary" :disabled="busy" @click="save(field)">{{i18n.t('pdf_corpus.save_field_value','Save value')}}</button></div></div></article></div></details>
  <div v-if="!fields.length" class="resolved" role="status">{{i18n.t('pdf_corpus.metadata_record_resolved','No record metadata is available yet.')}}</div>
</section>
</template>

<style scoped>
.metadata-review{padding:14px;background:var(--card)}.metadata-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;margin-bottom:10px}.metadata-head h3{margin:0 0 3px;font-size:1rem}.metadata-head p{margin:0;max-width:72ch;font-size:.8125rem;line-height:1.5;color:var(--muted)}.review-status{flex:none;padding:5px 9px;border-radius:999px;background:#edf8f1;color:#285c39;font-size:.8125rem;font-weight:800}.review-status[data-state="attention"]{background:#fff4d6;color:#6a5100}.review-status[data-state="processing"]{background:#eef4ff;color:#294c7a}.enrichment-note{margin:0 0 10px;padding:9px 11px;border:1px solid #b9cce6;border-radius:8px;background:#f4f8ff;color:#294c7a;font-size:.8125rem;line-height:1.45}.metadata-table{border:1px solid var(--line);border-radius:10px;overflow:hidden}.metadata-row{background:var(--card);border-bottom:1px solid var(--line)}.metadata-row:last-child{border-bottom:0}.metadata-row.unresolved{box-shadow:inset 3px 0 #d5a52b}.metadata-summary{display:grid;grid-template-columns:minmax(150px,.75fr) minmax(0,1.2fr) auto;gap:12px;align-items:center;padding:10px 12px}.field-label{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.field-label b{font-size:.8125rem}.field-value{display:grid;gap:3px;min-width:0;font-size:.8125rem;overflow-wrap:anywhere}.proposal{display:inline-flex;align-items:center;width:max-content;max-width:100%;padding:3px 7px;border:1px solid #dfc66f;border-radius:999px;background:#fff8e9;font-size:.8125rem;line-height:1.3;color:#6b5200}.proposal[data-strong="true"]{color:#285c39;font-weight:700}.field-actions{display:flex;gap:7px;align-items:center}.evidence-link,.link-button{border:0;background:none;color:var(--accent);font-size:.8125rem;font-weight:700;cursor:pointer}.decision-editor{display:grid;gap:8px;padding:10px 12px 12px;background:var(--soft);border-top:1px solid var(--line)}.decision-reason{margin:0;color:var(--muted);font-size:.8125rem;line-height:1.45}.decision-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.decision-controls>.control{flex:1 1 220px}.boolean-choice{display:flex;gap:14px;margin:0;padding:0;border:0}.boolean-choice label{display:flex;align-items:center;gap:6px;min-height:40px}.decision-meta{display:flex;gap:10px;align-items:center;flex-wrap:wrap;color:var(--muted);font-size:.8125rem}.saved{color:#285c39;font-weight:700}.inherited-metadata{margin-top:14px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}.inherited-metadata>summary{padding:10px 12px;cursor:pointer;font-size:.875rem;font-weight:750}.inherited-metadata>summary span{margin-left:5px;color:var(--muted)}.inherited-metadata>p{margin:0;padding:0 12px 10px;color:var(--muted);font-size:.8125rem;line-height:1.5}.inherited-metadata .metadata-table{margin:0 10px 10px}.resolved{padding:12px;color:var(--muted);font-size:.875rem}@media(max-width:760px){.metadata-head,.metadata-summary{grid-template-columns:1fr;display:grid}.field-actions{justify-content:flex-start}}
</style>
